async function testWebcamPermissions() {
    // Vérifier si l'utilisateur a accordé l'accès à la webcam
    const permission = await navigator.mediaDevices.getUserMedia({ video: true });

    if (permission.state === 'granted') {
        console.log('Accès à la webcam accordé.');

